38	@InterfaceAudience.Private
39	public class JournalNodeHttpServer {
40	  public static final String JN_ATTRIBUTE_KEY = "localjournal";
41	
42	  private HttpServer2 httpServer;
43	  private final JournalNode localJournalNode;
44	
45	  private InetSocketAddress httpAddress;
46	  private InetSocketAddress httpsAddress;
47	  private final InetSocketAddress bindAddress;
48	
49	  private final Configuration conf;
50	
51	  JournalNodeHttpServer(Configuration conf, JournalNode jn,
52	      InetSocketAddress bindAddress) {
53	    this.conf = conf;
54	    this.localJournalNode = jn;
55	    this.bindAddress = bindAddress;
56	  }
57	
58	  void start() throws IOException {
59	    final InetSocketAddress httpAddr = bindAddress;
60	
61	    final String httpsAddrString = conf.get(
62	        DFSConfigKeys.DFS_JOURNALNODE_HTTPS_ADDRESS_KEY,
63	        DFSConfigKeys.DFS_JOURNALNODE_HTTPS_ADDRESS_DEFAULT);
64	    InetSocketAddress httpsAddr = NetUtils.createSocketAddr(httpsAddrString);
65	
66	    if (httpsAddr != null) {
67	      // If DFS_JOURNALNODE_HTTPS_BIND_HOST_KEY exists then it overrides the
68	      // host name portion of DFS_NAMENODE_HTTPS_ADDRESS_KEY.
69	      final String bindHost =
70	          conf.getTrimmed(DFSConfigKeys.DFS_JOURNALNODE_HTTPS_BIND_HOST_KEY);
71	      if (bindHost != null && !bindHost.isEmpty()) {
72	        httpsAddr = new InetSocketAddress(bindHost, httpsAddr.getPort());
73	      }
74	    }
75	
76	    HttpServer2.Builder builder = DFSUtil.httpServerTemplateForNNAndJN(conf,
77	        httpAddr, httpsAddr, "journal",
78	        DFSConfigKeys.DFS_JOURNALNODE_KERBEROS_INTERNAL_SPNEGO_PRINCIPAL_KEY,
79	        DFSConfigKeys.DFS_JOURNALNODE_KEYTAB_FILE_KEY);
80	
81	    httpServer = builder.build();
82	    httpServer.setAttribute(JN_ATTRIBUTE_KEY, localJournalNode);
83	    httpServer.setAttribute(JspHelper.CURRENT_CONF, conf);
84	    httpServer.addInternalServlet("getJournal", "/getJournal",
85	        GetJournalEditServlet.class, true);
86	    httpServer.start();
87	
88	    HttpConfig.Policy policy = DFSUtil.getHttpPolicy(conf);
89	    int connIdx = 0;
90	    if (policy.isHttpEnabled()) {
91	      httpAddress = httpServer.getConnectorAddress(connIdx++);
92	      conf.set(DFSConfigKeys.DFS_JOURNALNODE_HTTP_ADDRESS_KEY,
93	          NetUtils.getHostPortString(httpAddress));
94	    }
95	
96	    if (policy.isHttpsEnabled()) {
97	      httpsAddress = httpServer.getConnectorAddress(connIdx);
98	      conf.set(DFSConfigKeys.DFS_JOURNALNODE_HTTPS_ADDRESS_KEY,
99	          NetUtils.getHostPortString(httpsAddress));
100	    }
101	  }
