  public void testConfAbnormalHandlerNumber() {
    int confHandlerCount = jn.getConf().getInt(
        DFSConfigKeys.DFS_JOURNALNODE_HANDLER_COUNT_KEY,
        DFSConfigKeys.DFS_JOURNALNODE_HANDLER_COUNT_DEFAULT);
